const text = String($json.output || '');

// protect URLs (Zoom links etc.) so the markdown-strip regex can't corrupt them
const urls = [];
const protectedText = text.replace(/https?:\/\/\S+/g, (m) => {
  urls.push(m);
  return '@@URL' + (urls.length - 1) + '@@';
});

const cleaned = protectedText
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/__(.*?)__/g, '$1')
  .replace(/_(.*?)_/g, '$1');

const cleanText = cleaned.replace(/@@URL(\d+)@@/g, (m, i) => urls[Number(i)]);

return [{
  json: {
    ...$json,
    output: cleanText
  }
}];

