const ctx = $('Build Context').item.json;
const p = $input.first().json || {};

const fullName = (
  p.name ||
  (p.from && p.from.name) ||
  [p.first_name, p.last_name].filter(Boolean).join(' ') ||
  ''
).trim();
const realName = fullName || (p.username ? String(p.username).trim() : '');

return [{
  json: {
    ...ctx,
    senderName: realName || ctx.senderName
  }
}];
